<script setup>
import { Head, router, useForm } from '@inertiajs/vue3';
import { computed, ref } from 'vue';
import AdminLayout from '../../Layouts/AdminLayout.vue';
import Icon from '../../Components/Icon.vue';

const props = defineProps({ productCategories: Array, serviceCategories: Array, brands: Array, view: String, counts: Object });
const trash = computed(() => props.view === 'trash');
const tab = ref('product');
const categoryForm = useForm({ id: null, name: '', slug: '', type: 'product', description: '', meta_title: '', meta_description: '', image: null, image_url: '', current_image_url: '', is_active: true, sort_order: 0 });
const brandForm = useForm({ id: null, name: '', logo: null, current_logo_url: '' });
const editingCategory = computed(() => !!categoryForm.id); const editingBrand = computed(() => !!brandForm.id); const activeCategories = computed(() => tab.value === 'service' ? props.serviceCategories : props.productCategories);
const switchView = (view) => router.get('/admin/catalog', { view: view || undefined });
const switchTab = (value) => { tab.value = value; if (value === 'product' || value === 'service') categoryForm.type = value; };
const resetCategory = () => { categoryForm.reset(); categoryForm.clearErrors(); Object.assign(categoryForm, { id: null, name: '', slug: '', type: tab.value === 'service' ? 'service' : 'product', description: '', meta_title: '', meta_description: '', image: null, image_url: '', current_image_url: '', is_active: true, sort_order: 0 }); };
const editCategory = (category) => { tab.value = category.type; Object.assign(categoryForm, { id: category.id, name: category.name, slug: category.slug, type: category.type, description: category.description || '', meta_title: category.meta_title || '', meta_description: category.meta_description || '', image: null, image_url: '', current_image_url: category.image_url || '', is_active: category.is_active, sort_order: category.sort_order || 0 }); window.scrollTo({ top: 0, behavior: 'smooth' }); };
const saveCategory = () => { const url = editingCategory.value ? `/admin/catalog/categories/${categoryForm.id}` : '/admin/catalog/categories'; categoryForm.post(url, { forceFormData: true, preserveScroll: true, onSuccess: resetCategory }); };
const removeCategory = (category) => confirm(`Delete “${category.name}”? It will be moved to Trash and can be restored.`) && router.delete(`/admin/catalog/categories/${category.id}`, { preserveScroll: true });
const restoreCategory = (category) => router.post(`/admin/catalog/categories/${category.id}/restore`, {}, { preserveScroll: true });
const resetBrand = () => { brandForm.reset(); brandForm.clearErrors(); Object.assign(brandForm, { id: null, name: '', logo: null, current_logo_url: '' }); };
const editBrand = (brand) => { Object.assign(brandForm, { id: brand.id, name: brand.name, logo: null, current_logo_url: brand.logo_url || '' }); tab.value = 'brand'; window.scrollTo({ top: 0, behavior: 'smooth' }); };
const saveBrand = () => { const url = editingBrand.value ? `/admin/catalog/brands/${brandForm.id}` : '/admin/catalog/brands'; brandForm.post(url, { forceFormData: true, preserveScroll: true, onSuccess: resetBrand }); };
const removeBrand = (brand) => confirm(`Delete “${brand.name}”? It will be moved to Trash and can be restored.`) && router.delete(`/admin/catalog/brands/${brand.id}`, { preserveScroll: true });
const restoreBrand = (brand) => router.post(`/admin/catalog/brands/${brand.id}/restore`, {}, { preserveScroll: true });
</script>

<template>
    <AdminLayout><Head title="Categories & Brands" />
        <div class="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p class="section-kicker">Catalogue structure</p><h1 class="section-title">Categories and brands</h1><p class="mt-2 max-w-2xl text-sm leading-6 text-slate-500">Manage product categories, service categories and brands.</p></div><button :class="trash ? 'btn-light' : 'btn-danger'" @click="switchView(trash ? '' : 'trash')"><Icon :name="trash ? 'arrow-left-2' : 'trash'" :size="16" /> {{ trash ? 'Back to catalogue' : `Open Trash (${counts.trash})` }}</button></div>
        <div class="mt-7 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><button class="metric-card text-left transition hover:border-prinx-300" @click="switchTab('product')"><p class="text-[10px] font-black uppercase tracking-[.15em] text-prinx-600">Product categories</p><b class="mt-2 block text-3xl font-black">{{ counts.product_categories }}</b><p class="mt-1 text-xs text-slate-500">Used by store products</p></button><button class="metric-card text-left transition hover:border-prinx-300" @click="switchTab('service')"><p class="text-[10px] font-black uppercase tracking-[.15em] text-prinx-600">Service categories</p><b class="mt-2 block text-3xl font-black">{{ counts.service_categories }}</b><p class="mt-1 text-xs text-slate-500">Used by technical services</p></button><button class="metric-card text-left transition hover:border-prinx-300" @click="switchTab('brand')"><p class="text-[10px] font-black uppercase tracking-[.15em] text-slate-500">Brands</p><b class="mt-2 block text-3xl font-black">{{ counts.brands }}</b><p class="mt-1 text-xs text-slate-500">Product manufacturers</p></button><button class="metric-card text-left transition hover:border-red-200" @click="switchView('trash')"><p class="text-[10px] font-black uppercase tracking-[.15em] text-red-500">Trash</p><b class="mt-2 block text-3xl font-black">{{ counts.trash }}</b><p class="mt-1 text-xs text-slate-500">Soft-deleted records</p></button></div>
        <div v-if="!trash" class="mt-6 flex flex-wrap gap-2 rounded-[10px] border border-slate-200 bg-white p-2"><button :class="['tab-button', tab === 'product' ? 'bg-slate-950 text-white' : 'text-slate-600 hover:bg-slate-100']" @click="switchTab('product')">Product categories</button><button :class="['tab-button', tab === 'service' ? 'bg-slate-950 text-white' : 'text-slate-600 hover:bg-slate-100']" @click="switchTab('service')">Service categories</button><button :class="['tab-button', tab === 'brand' ? 'bg-slate-950 text-white' : 'text-slate-600 hover:bg-slate-100']" @click="switchTab('brand')">Brands</button></div>
        <div v-if="!trash && tab !== 'brand'" class="mt-6 grid gap-6 xl:grid-cols-[360px_1fr]"><section class="card h-fit overflow-hidden xl:sticky xl:top-24"><div class="border-b border-slate-200 bg-slate-50 px-5 py-4"><p class="text-[10px] font-black uppercase tracking-[.15em] text-prinx-600">{{ categoryForm.type }} category</p><h2 class="mt-1 text-lg font-black">{{ editingCategory ? 'Edit category' : 'Create a category' }}</h2></div><form class="space-y-4 p-5" @submit.prevent="saveCategory"><div><label class="label">Category type</label><div class="grid grid-cols-2 gap-2"><button type="button" :class="['rounded-[9px] border px-3 py-2.5 text-sm font-black', categoryForm.type === 'product' ? 'border-prinx-500 bg-prinx-50 text-prinx-700' : 'border-slate-200 text-slate-500']" @click="categoryForm.type='product'; tab='product'">Product</button><button type="button" :class="['rounded-[9px] border px-3 py-2.5 text-sm font-black', categoryForm.type === 'service' ? 'border-prinx-500 bg-prinx-50 text-prinx-700' : 'border-slate-200 text-slate-500']" @click="categoryForm.type='service'; tab='service'">Service</button></div><p class="error">{{ categoryForm.errors.type }}</p></div><div><label class="label">Category name *</label><input v-model="categoryForm.name" class="input" placeholder="e.g. Smartphones"><p class="error">{{ categoryForm.errors.name }}</p></div><div><label class="label">URL slug</label><input v-model="categoryForm.slug" class="input" placeholder="Generated automatically"><p class="error">{{ categoryForm.errors.slug }}</p></div><div><label class="label">Description</label><textarea v-model="categoryForm.description" class="input" rows="4" placeholder="A short customer-friendly description"></textarea></div><div><label class="label">SEO title</label><input v-model="categoryForm.meta_title" class="input" maxlength="190" placeholder="e.g. Smartphones in Dodoma | Prinx Tech"><p class="error">{{ categoryForm.errors.meta_title }}</p></div><div><label class="label">SEO description</label><textarea v-model="categoryForm.meta_description" class="input" rows="3" maxlength="180" placeholder="Search-result description for this category"></textarea><p class="error">{{ categoryForm.errors.meta_description }}</p></div><div class="grid grid-cols-2 gap-3"><div><label class="label">Sort order</label><input v-model="categoryForm.sort_order" type="number" min="0" class="input"></div><label class="mt-7 flex items-center gap-2 text-sm font-bold text-slate-700"><input v-model="categoryForm.is_active" type="checkbox" class="h-4 w-4 accent-prinx-500"> Active</label></div><div><label class="label">Category image</label><input type="file" class="input" accept="image/jpeg,image/png,image/webp" @change="categoryForm.image=$event.target.files[0]"><p class="image-spec">1200 × 800 px (3:2) · max 6 MB · automatically converted to WebP</p><p class="error">{{ categoryForm.errors.image }}</p></div><div><label class="label">Or image URL</label><input v-model="categoryForm.image_url" type="url" class="input" placeholder="https://..."><p class="image-spec">Use the same 1200 × 800 px proportion. Remote URLs are not converted.</p></div><div v-if="editingCategory && categoryForm.current_image_url"><p class="label">Current image</p><img :src="categoryForm.current_image_url" :alt="categoryForm.name" class="aspect-[3/2] w-full rounded-[10px] border border-slate-200 bg-slate-50 object-cover"></div><button class="btn-primary w-full py-3" :disabled="categoryForm.processing">{{ categoryForm.processing ? 'Saving...' : editingCategory ? 'Save category' : 'Create category' }}</button><button v-if="editingCategory" type="button" class="w-full text-sm font-bold text-slate-500 hover:text-prinx-600" @click="resetCategory">Cancel editing</button></form></section>
            <section><div class="mb-4 flex items-center justify-between"><div><h2 class="text-lg font-black capitalize">{{ tab }} categories</h2><p class="mt-1 text-xs text-slate-500">Public catalogue categories.</p></div><span class="status bg-prinx-50 text-prinx-700">{{ activeCategories.length }} categories</span></div><div class="grid gap-4 md:grid-cols-2"><article v-for="category in activeCategories" :key="category.id" class="group category-card"><div class="flex gap-4 p-4"><img :src="category.image_url" :alt="category.name" class="h-24 w-24 shrink-0 rounded-[10px] border border-slate-200 bg-slate-50 object-cover"><div class="min-w-0 flex-1"><div class="flex items-start justify-between gap-3"><div><p class="text-[10px] font-black uppercase tracking-[.14em] text-prinx-600">{{ category.type }} category</p><h3 class="mt-1 truncate text-lg font-black">{{ category.name }}</h3></div><span :class="['status', category.is_active ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-100 text-slate-500']">{{ category.is_active ? 'Active' : 'Hidden' }}</span></div><p class="mt-2 line-clamp-2 text-xs leading-5 text-slate-500">{{ category.description || 'No description added.' }}</p><p class="mt-3 text-xs font-bold text-slate-700">{{ category.type === 'product' ? category.products_count : category.services_count }} assigned {{ category.type === 'product' ? 'products' : 'services' }} · Order {{ category.sort_order }}</p></div></div><div class="flex justify-end gap-2 border-t border-slate-100 bg-slate-50/70 px-4 py-3"><button class="btn-light px-3 py-2" @click="editCategory(category)">Edit</button><button class="btn-danger" @click="removeCategory(category)">Delete</button></div></article><div v-if="!activeCategories.length" class="card col-span-full py-16 text-center"><p class="font-black text-slate-700">No {{ tab }} categories yet</p><p class="mt-1 text-xs text-slate-400">No category has been added.</p></div></div></section></div>
        <div v-if="!trash && tab === 'brand'" class="mt-6 grid gap-6 xl:grid-cols-[360px_1fr]"><section class="card h-fit overflow-hidden xl:sticky xl:top-24"><div class="border-b border-slate-200 bg-slate-50 px-5 py-4"><p class="text-[10px] font-black uppercase tracking-[.15em] text-prinx-600">Product brand</p><h2 class="mt-1 text-lg font-black">{{ editingBrand ? 'Edit brand' : 'Add a brand' }}</h2></div><form class="space-y-4 p-5" @submit.prevent="saveBrand"><div><label class="label">Brand name *</label><input v-model="brandForm.name" class="input" placeholder="e.g. Samsung"><p class="error">{{ brandForm.errors.name }}</p></div><div><label class="label">Brand logo {{ editingBrand ? '' : '*' }}</label><input type="file" class="input" accept="image/jpeg,image/png,image/webp" @change="brandForm.logo=$event.target.files[0]"><p class="image-spec">PNG, JPG or WebP · max 4 MB · transparent PNG logos are supported</p><p class="error">{{ brandForm.errors.logo }}</p></div><div v-if="editingBrand && brandForm.current_logo_url"><p class="label">Current logo</p><div class="flex min-h-24 items-center justify-center rounded-[10px] border border-slate-200 bg-white p-4"><img :src="brandForm.current_logo_url" :alt="brandForm.name" class="max-h-16 max-w-full object-contain"></div></div><button class="btn-primary w-full py-3" :disabled="brandForm.processing">{{ brandForm.processing ? 'Saving...' : editingBrand ? 'Save brand' : 'Add brand' }}</button><button v-if="editingBrand" type="button" class="w-full text-sm font-bold text-slate-500 hover:text-prinx-600" @click="resetBrand">Cancel editing</button></form></section><section><div class="mb-4 flex items-center justify-between"><div><h2 class="text-lg font-black">Product brands</h2><p class="mt-1 text-xs text-slate-500">Add a brand name and its official logo.</p></div><span class="status bg-slate-100 text-slate-700">{{ brands.length }} brands</span></div><div class="grid gap-4 md:grid-cols-2 xl:grid-cols-3"><article v-for="brand in brands" :key="brand.id" class="card p-5"><div class="flex h-20 items-center justify-center rounded-[10px] border border-slate-100 bg-white p-3"><img v-if="brand.logo_url" :src="brand.logo_url" :alt="`${brand.name} logo`" class="max-h-14 max-w-full object-contain"><div v-else class="flex h-12 w-12 items-center justify-center rounded-[10px] bg-slate-950 text-lg font-black text-white">{{ brand.name.charAt(0) }}</div></div><h3 class="mt-4 text-lg font-black">{{ brand.name }}</h3><p class="mt-1 text-xs font-semibold text-slate-500">{{ brand.products_count }} assigned products</p><div class="mt-5 flex gap-2"><button class="btn-light flex-1 px-3 py-2" @click="editBrand(brand)">Edit</button><button class="btn-danger" @click="removeBrand(brand)">Delete</button></div></article><div v-if="!brands.length" class="card col-span-full py-16 text-center"><p class="font-black text-slate-700">No brands yet</p><p class="mt-1 text-xs text-slate-400">Add your first product brand using the form.</p></div></div></section></div>
        <section v-if="trash" class="mt-6"><div class="rounded-[10px] border border-red-200 bg-red-50 p-5"><div class="flex gap-3"><div class="flex h-10 w-10 shrink-0 items-center justify-center rounded-[10px] bg-red-100 text-red-600"><Icon name="warning-2" :size="20" /></div><div><h2 class="font-black text-red-900">Soft-delete Trash</h2><p class="mt-1 text-sm leading-6 text-red-700">Deleted items remain recoverable.</p></div></div></div><div class="mt-6 grid gap-6 xl:grid-cols-3"><div><h3 class="mb-3 font-black">Product categories</h3><div class="space-y-3"><div v-for="category in productCategories" :key="category.id" class="card flex items-center justify-between gap-3 p-4"><div><b>{{ category.name }}</b><p class="mt-1 text-xs text-slate-500">Deleted {{ new Date(category.deleted_at).toLocaleString() }}</p></div><button class="btn-primary px-3 py-2" @click="restoreCategory(category)">Restore</button></div><p v-if="!productCategories.length" class="rounded-[10px] border border-dashed border-slate-300 p-5 text-center text-xs text-slate-400">No deleted product categories.</p></div></div><div><h3 class="mb-3 font-black">Service categories</h3><div class="space-y-3"><div v-for="category in serviceCategories" :key="category.id" class="card flex items-center justify-between gap-3 p-4"><div><b>{{ category.name }}</b><p class="mt-1 text-xs text-slate-500">Deleted {{ new Date(category.deleted_at).toLocaleString() }}</p></div><button class="btn-primary px-3 py-2" @click="restoreCategory(category)">Restore</button></div><p v-if="!serviceCategories.length" class="rounded-[10px] border border-dashed border-slate-300 p-5 text-center text-xs text-slate-400">No deleted service categories.</p></div></div><div><h3 class="mb-3 font-black">Brands</h3><div class="space-y-3"><div v-for="brand in brands" :key="brand.id" class="card flex items-center justify-between gap-3 p-4"><div class="flex min-w-0 items-center gap-3"><img v-if="brand.logo_url" :src="brand.logo_url" :alt="brand.name" class="h-10 w-14 shrink-0 rounded-[6px] border border-slate-200 bg-white object-contain p-1"><div class="min-w-0"><b class="block truncate">{{ brand.name }}</b><p class="mt-1 text-xs text-slate-500">Deleted {{ new Date(brand.deleted_at).toLocaleString() }}</p></div></div><button class="btn-primary px-3 py-2" @click="restoreBrand(brand)">Restore</button></div><p v-if="!brands.length" class="rounded-[10px] border border-dashed border-slate-300 p-5 text-center text-xs text-slate-400">No deleted brands.</p></div></div></div></section>
    </AdminLayout>
</template>
